end $function$

CREATE OR REPLACE FUNCTION app_private.manage_aquarium_tank(p_tank_id uuid, p_action text, p_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid:=auth.uid(); v_tank public.aquarium_tanks; v_name text;
begin
 if v_uid is null then raise exception 'AUTH_REQUIRED'; end if;
 select * into v_tank from public.aquarium_tanks where id=p_tank_id and user_id=v_uid for update;
 if not found then raise exception 'TANK_NOT_FOUND'; end if;
 if p_action='rename' then
  v_name:=btrim(p_value);
  if v_name is null or char_length(v_name) not between 1 and 20 or v_name ~ '[[:cntrl:]]' then raise exception 'INVALID_TANK_NAME'; end if;
  update public.aquarium_tanks set name=v_name where id=p_tank_id;
 elsif p_action='equip' then
  if p_value is null or not exists(select 1 from public.aquarium_backgrounds where id=p_value) then raise exception 'INVALID_ITEM'; end if;
  if p_value<>'default' and not exists(select 1 from public.owned_aquarium_backgrounds where user_id=v_uid and background_id=p_value) then raise exception 'BACKGROUND_NOT_OWNED'; end if;
  update public.aquarium_tanks set background_id=p_value where id=p_tank_id;
  if v_tank.is_default then update public.player_aquariums set background_id=p_value where user_id=v_uid; end if;
 else raise exception 'INVALID_TRADE';
 end if;
 return app_private.aquarium_state();
end $function$

CREATE OR REPLACE FUNCTION app_private.memory_game(p_action text, p_operation_id uuid DEFAULT NULL::uuid, p_run_id uuid DEFAULT NULL::uuid, p_card integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid:=auth.uid();r public.memory_game_runs;b app_private.memory_game_boards;v_gold integer;v_deck text[];
begin
 if v_uid is null then raise exception 'AUTH_REQUIRED'; end if;
 if p_action is null or p_action not in ('state','start','flip','clear','leave') then raise exception 'INVALID_MEMORY_ACTION'; end if;
 if p_action='state' then
  if p_run_id is null then select * into r from public.memory_game_runs where user_id=v_uid and finished_at is null and abandoned_at is null;
  else select * into r from public.memory_game_runs where user_id=v_uid and id=p_run_id;
   if not found then raise exception 'MEMORY_RUN_NOT_FOUND'; end if;
  end if;
  return app_private.memory_response(r.id);
 end if;
 perform app_private.get_gold_wallet();
 select gold into v_gold from public.player_wallets where user_id=v_uid for update;
 if p_action='start' then
  if p_operation_id is null then raise exception 'INVALID_OPERATION'; end if;
  select * into r from public.memory_game_runs where user_id=v_uid and operation_id=p_operation_id;
  if found then return app_private.memory_response(r.id); end if;
  select * into r from public.memory_game_runs where user_id=v_uid and finished_at is null and abandoned_at is null;
  if found then return app_private.memory_response(r.id); end if;
  if v_gold<10 then raise exception 'INSUFFICIENT_GOLD'; end if;
  select array_agg(face order by shuffle) into v_deck from (
   select face,random() shuffle from unnest(array['starfish','shell','pearl','rod','float','lighthouse','boat','treasure','coral','fish','shrimp','letter']) face cross join generate_series(1,2)) s;
  v_deck:=v_deck[1:12]||array['pongi']||v_deck[13:24];
  insert into public.memory_game_runs(user_id,operation_id) values(v_uid,p_operation_id) returning * into r;
  insert into app_private.memory_game_boards(run_id,deck) values(r.id,v_deck);
  update public.player_wallets set gold=gold-10,updated_at=clock_timestamp() where user_id=v_uid;
  insert into public.gold_transactions(user_id,operation_id,action,item_id,delta) values(v_uid,p_operation_id,'buy','arcade:memory',-10);
  return app_private.memory_response(r.id);
 end if;
 select * into r from public.memory_game_runs where id=p_run_id and user_id=v_uid for update;
 if not found then raise exception 'MEMORY_RUN_NOT_FOUND'; end if;
 if r.finished_at is not null or r.abandoned_at is not null then return app_private.memory_response(r.id); end if;
 select * into strict b from app_private.memory_game_boards where run_id=r.id;
 if p_action='leave' then
  update public.memory_game_runs set abandoned_at=clock_timestamp() where id=r.id;
  return app_private.memory_response(r.id);
 end if;
 if p_action='clear' then
  if b.clear_at is null or clock_timestamp()<b.clear_at then return app_private.memory_response(r.id); end if;
  update app_private.memory_game_boards set first_card=null,second_card=null,clear_at=null where run_id=r.id;
  return app_private.memory_response(r.id);
 end if;
 if p_card is null or p_card not between 1 and 25 then raise exception 'INVALID_MEMORY_CARD'; end if;
 if p_card=13 or p_card=any(b.matched) or p_card=b.first_card or b.second_card is not null then return app_private.memory_response(r.id); end if;
 if r.timer_started_at is null then
  update public.memory_game_runs set timer_started_at=clock_timestamp() where id=r.id returning * into r;
 end if;
 if b.first_card is null then update app_private.memory_game_boards set first_card=p_card where run_id=r.id;
 else
  update public.memory_game_runs set moves=moves+1 where id=r.id;
  if b.deck[b.first_card]=b.deck[p_card] then
   b.matched:=b.matched||array[b.first_card,p_card];
   update app_private.memory_game_boards set matched=b.matched,first_card=null,second_card=null,clear_at=null where run_id=r.id;
   if cardinality(b.matched)=24 then
    update public.memory_game_runs set finished_at=clock_timestamp(),elapsed_ms=floor(extract(epoch from(clock_timestamp()-r.timer_started_at))*1000)::bigint where id=r.id;
   end if;
  else update app_private.memory_game_boards set second_card=p_card,clear_at=clock_timestamp()+interval '900 milliseconds' where run_id=r.id;
  end if;
 end if;
 return app_private.memory_response(r.id);
end $function$

CREATE OR REPLACE FUNCTION app_private.memory_leaderboard(p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_start timestamptz:=date_trunc('week',clock_timestamp() at time zone 'Asia/Seoul') at time zone 'Asia/Seoul';v_rows jsonb;v_total bigint;
begin
 if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;
 if p_offset is null or p_offset<0 then raise exception 'INVALID_OFFSET'; end if;
 select count(distinct user_id) into v_total from public.memory_game_runs where finished_at>=v_start and abandoned_at is null;
 select coalesce(jsonb_agg(to_jsonb(t) order by t.rank),'[]'::jsonb) into v_rows from (
 select row_number() over(order by r.elapsed_ms,r.finished_at,r.id)+p_offset as rank,r.id,r.elapsed_ms as "elapsedMs",r.moves,
 coalesce(p.nickname,'섬 여행자') as nickname,r.user_id=auth.uid() as mine
 from (select * from (select distinct on(user_id) * from public.memory_game_runs where finished_at>=v_start and abandoned_at is null order by user_id,elapsed_ms,finished_at,id) best order by elapsed_ms,finished_at,id limit 20 offset p_offset) r
 left join public.player_profiles p on p.id=r.user_id) t;
 return jsonb_build_object('rows',v_rows,'total',v_total,'offset',p_offset,'pageSize',20,'weekStart',v_start,'weekEnd',v_start+interval '7 days');
end $function$

CREATE OR REPLACE FUNCTION app_private.memory_response(p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare r public.memory_game_runs;b app_private.memory_game_boards;v_cards jsonb;
begin
 if p_id is null then return jsonb_build_object('run',null,'serverNow',clock_timestamp()); end if;
 select * into strict r from public.memory_game_runs where id=p_id;
 select * into strict b from app_private.memory_game_boards where run_id=p_id;
 select jsonb_agg(case when i=13 or i=any(b.matched) or i=b.first_card or i=b.second_card then to_jsonb(b.deck[i]) else 'null'::jsonb end order by i) into v_cards from generate_series(1,25) i;
 return jsonb_build_object('serverNow',clock_timestamp(),'run',jsonb_build_object('id',r.id,'cards',v_cards,
 'matched',to_jsonb(b.matched),'first',b.first_card,'second',b.second_card,'clearAt',b.clear_at,
 'startedAt',r.timer_started_at,'elapsedMs',case when r.elapsed_ms is not null then r.elapsed_ms when r.timer_started_at is null then 0 else floor(extract(epoch from(clock_timestamp()-r.timer_started_at))*1000)::bigint end,
 'moves',r.moves,'finished',r.finished_at is not null,'abandoned',r.abandoned_at is not null));
end $function$

CREATE OR REPLACE FUNCTION app_private.move_collectibles(p_collectible_ids uuid[], p_tank_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid:=auth.uid();v_ids uuid[];v_count integer;v_occupancy integer;v_added integer;
begin
 if v_uid is null then raise exception 'AUTH_REQUIRED'; end if;
 if coalesce(cardinality(p_collectible_ids),0) not between 1 and 50 then raise exception 'INVALID_SELECTION'; end if;
 select array_agg(id order by id) into v_ids from(select distinct unnest(p_collectible_ids) as id) q;
 if cardinality(v_ids)<>cardinality(p_collectible_ids) or array_position(v_ids,null) is not null then raise exception 'INVALID_SELECTION'; end if;
 -- Serialize admissions to the same tank before locking individuals in ID order.
 if p_tank_id is not null then
  perform 1 from public.aquarium_tanks where id=p_tank_id and user_id=v_uid for update;
  if not found then raise exception 'TANK_NOT_FOUND'; end if;
 end if;
 perform 1 from public.player_collectibles where id=any(v_ids) and user_id=v_uid order by id for update;
 select count(*) into v_count from public.player_collectibles c join public.collectible_species s on s.id=c.species_id
 where c.id=any(v_ids) and c.user_id=v_uid and c.sold_at is null and c.escrow_gift_id is null and s.kind in ('fish','trash','decoration');
 if v_count<>cardinality(v_ids) then raise exception 'COLLECTIBLE_NOT_FOUND'; end if;
 if p_tank_id is not null then
  if exists(select 1 from public.player_collectibles where id=any(v_ids) and tank_id is not null and tank_id<>p_tank_id) then raise exception 'STORAGE_REQUIRED'; end if;
  select count(*) into v_added from public.player_collectibles where id=any(v_ids) and tank_id is null;
  select count(*) into v_occupancy from public.player_collectibles where tank_id=p_tank_id and user_id=v_uid and sold_at is null and escrow_gift_id is null;
  if v_added>0 and v_occupancy+v_added>50 then raise exception 'TANK_FULL'; end if;
 end if;
 update public.player_collectibles set tank_id=p_tank_id,position_x=null,position_y=null
 where id=any(v_ids) and tank_id is distinct from p_tank_id;
 return app_private.aquarium_state();
end $function$

CREATE OR REPLACE FUNCTION app_private.odd_even_game(p_action text, p_operation_id uuid DEFAULT NULL::uuid, p_run_id uuid DEFAULT NULL::uuid, p_round integer DEFAULT NULL::integer, p_choice text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid:=auth.uid();r public.odd_even_runs;v_gold integer;v_pearls integer;v_win boolean;
begin
 if v_uid is null then raise exception 'AUTH_REQUIRED';end if;
 if p_action is null or p_action not in ('state','start','answer','double','cashout') then raise exception 'INVALID_ODD_EVEN_ACTION';end if;
 if p_action='state' then
  select * into r from public.odd_even_runs where user_id=v_uid and finished_at is null;
  return app_private.odd_even_response(r.id);
 end if;
 perform app_private.get_gold_wallet();
 select gold into v_gold from public.player_wallets where user_id=v_uid for update;
 if p_action='start' then
  if p_operation_id is null then raise exception 'INVALID_OPERATION';end if;
  select * into r from public.odd_even_runs where user_id=v_uid and operation_id=p_operation_id;
  if found then return app_private.odd_even_response(r.id);end if;
  select * into r from public.odd_even_runs where user_id=v_uid and finished_at is null;
  if found then return app_private.odd_even_response(r.id);end if;
  if v_gold<10 then raise exception 'INSUFFICIENT_GOLD';end if;
  insert into public.odd_even_runs(user_id,operation_id) values(v_uid,p_operation_id) returning * into r;
  update public.player_wallets set gold=gold-10,updated_at=clock_timestamp() where user_id=v_uid;
  insert into public.gold_transactions(user_id,operation_id,action,item_id,delta) values(v_uid,p_operation_id,'buy','arcade:odd-even',-10);
  return app_private.odd_even_response(r.id);
 end if;
 select * into r from public.odd_even_runs where id=p_run_id and user_id=v_uid for update;
 if not found then raise exception 'ODD_EVEN_RUN_NOT_FOUND';end if;
 if r.finished_at is not null then return app_private.odd_even_response(r.id);end if;
 if p_round is null then raise exception 'INVALID_ROUND';end if;
 if p_round<r.round then return app_private.odd_even_response(r.id);end if;
 if p_round<>r.round then raise exception 'INVALID_ROUND';end if;
 if p_action='answer' then
  if r.stage<>'choose' then return app_private.odd_even_response(r.id);end if;
  if p_choice is null or p_choice not in ('odd','even') then raise exception 'INVALID_CHOICE';end if;
  v_pearls:=1+floor(random()*10)::integer;
  v_win:=(v_pearls%2=1)=(p_choice='odd');
  update public.odd_even_runs set pearls=v_pearls,choice=p_choice,stake=case when v_win then stake*2 else 0 end,
   wins=wins+case when v_win then 1 else 0 end,stage=case when v_win then 'decision' else 'lost' end,
   finished_at=case when v_win then null else clock_timestamp() end where id=r.id;
 elsif p_action='double' then
  if r.stage='choose' then return app_private.odd_even_response(r.id);end if;
  if r.wins>=20 then raise exception 'ODD_EVEN_LIMIT';end if;
  update public.odd_even_runs set stage='choose',round=round+1,pearls=null,choice=null where id=r.id;
 else
  if r.stage<>'decision' then raise exception 'ODD_EVEN_WIN_REQUIRED';end if;
  if v_gold>1000000000-r.stake then raise exception 'GOLD_LIMIT';end if;
  update public.player_wallets set gold=gold+r.stake,updated_at=clock_timestamp() where user_id=v_uid;
  insert into public.gold_transactions(user_id,operation_id,action,item_id,delta) values(v_uid,r.payout_operation_id,'charge','arcade:odd-even:'||r.id::text,r.stake);
  update public.odd_even_runs set stage='banked',finished_at=clock_timestamp() where id=r.id;
 end if;
 return app_private.odd_even_response(r.id);
end $function$

CREATE OR REPLACE FUNCTION app_private.odd_even_leaderboard(p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_rows jsonb;v_total bigint;
begin
 if auth.uid() is null then raise exception 'AUTH_REQUIRED';end if;
 if p_offset is null or p_offset<0 then raise exception 'INVALID_OFFSET';end if;
 select count(distinct user_id) into v_total from public.odd_even_runs where stage='banked';
 select coalesce(jsonb_agg(to_jsonb(t) order by t.rank),'[]'::jsonb) into v_rows from (
  select row_number() over(order by r.stake desc,r.finished_at,r.id)+p_offset as rank,r.id,r.stake as gold,r.wins,
   coalesce(p.nickname,'섬 여행자') as nickname,r.user_id=auth.uid() as mine,
   r.user_id as "userId",p.friend_code as "friendCode",
   (select f.status from public.friend_requests f where f.status in ('pending','accepted')
    and ((f.sender_id=auth.uid() and f.recipient_id=r.user_id) or (f.recipient_id=auth.uid() and f.sender_id=r.user_id))
    order by f.created_at desc limit 1) as "friendStatus"
  from (select * from (select distinct on(user_id) * from public.odd_even_runs where stage='banked' order by user_id,stake desc,finished_at,id) best order by stake desc,finished_at,id limit 20 offset p_offset) r
  left join public.player_profiles p on p.id=r.user_id
 ) t;
 return jsonb_build_object('rows',v_rows,'total',v_total);
end $function$

CREATE OR REPLACE FUNCTION app_private.owned_collectibles()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid:=auth.uid();
begin
 if v_uid is null then raise exception 'AUTH_REQUIRED'; end if;
 return coalesce((select jsonb_agg(to_jsonb(c)||jsonb_build_object('species',app_private.species_payload(s.id,c.map_region_id)) order by c.acquired_at desc)
 from public.player_collectibles c join public.collectible_species s on s.id=c.species_id where c.user_id=v_uid and c.sold_at is null and c.escrow_gift_id is null),'[]'::jsonb);
end $function$

CREATE OR REPLACE FUNCTION app_private.place_collectible(p_collectible_id uuid, p_tank_id uuid, p_x numeric, p_y numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid:=auth.uid(); v_item public.player_collectibles;
begin
 if v_uid is null then raise exception 'AUTH_REQUIRED'; end if;
 if p_x is null or p_y is null or not(p_x between 0 and 1) or not(p_y between 0 and 1) then raise exception 'INVALID_POSITION'; end if;
 if not exists(select 1 from public.aquarium_tanks where id=p_tank_id and user_id=v_uid) then raise exception 'TANK_NOT_FOUND'; end if;
 select * into v_item from public.player_collectibles where id=p_collectible_id and user_id=v_uid and sold_at is null and escrow_gift_id is null for update;
 if not found or v_item.tank_id is distinct from p_tank_id then raise exception 'COLLECTIBLE_NOT_FOUND'; end if;
 if not exists(select 1 from public.collectible_species where id=v_item.species_id and kind in ('fish','trash','decoration')) then raise exception 'INVALID_ITEM'; end if;
 update public.player_collectibles set position_x=p_x,position_y=p_y where id=v_item.id;
 return jsonb_build_object('id',v_item.id,'position_x',p_x,'position_y',p_y);
end $function$

CREATE OR REPLACE FUNCTION app_private.react_to_collectible_gift(p_gift_id uuid, p_reaction text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid:=auth.uid();g public.collectible_gifts;v_title text;
begin
 if v_uid is null then raise exception 'AUTH_REQUIRED'; end if;
 if p_reaction is null or p_reaction not in ('thumbs_up','heart','thanks','laugh','celebrate') then raise exception 'INVALID_REACTION'; end if;
 select * into g from public.collectible_gifts where id=p_gift_id and recipient_id=v_uid for update;
 if not found then raise exception 'GIFT_NOT_FOUND'; end if;
 if g.status<>'claimed' then raise exception 'GIFT_NOT_CLAIMED'; end if;
 if g.reaction is not null then
  if g.reaction<>p_reaction then raise exception 'GIFT_ALREADY_REACTED'; end if;
  return to_jsonb(g);
 end if;
 update public.collectible_gifts set reaction=p_reaction,reacted_at=now() where id=g.id returning * into g;
 v_title:=case p_reaction when 'thumbs_up' then '따봉을 보냈어요' when 'heart' then '하트를 보냈어요' when 'thanks' then '고마움을 보냈어요' when 'laugh' then '웃음을 보냈어요' else '축하를 보냈어요' end;
 if g.sender_id is not null then
  insert into public.notifications(recipient_id,actor_id,category,kind,title,body,gift_id) values(g.sender_id,v_uid,'gift','gift_reaction',v_title,g.recipient_name||'님이 선물에 답장했어요.',g.id) on conflict do nothing;
 end if;
 return to_jsonb(g);
end $function$

CREATE OR REPLACE FUNCTION app_private.region_map()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
